const {test}=require('node:test');
const assert=require('node:assert/strict');
const {family,plan,createApi,list,activeRuns}=require('./cache-retention.cjs');
const DAY=86400000,now=Date.parse('2026-10-22T12:00:00Z');
function c(id,days=2,extra={}) {return {id,key:`node-cache-Linux-x64-npm-${id.toString(16).repeat(8)}`,ref:'refs/heads/main',version:'v1',created_at:new Date(now-days*DAY).toISOString(),last_accessed_at:new Date(now-days*DAY).toISOString(),size_in_bytes:100,...extra};}
function p(caches,extra={}) {return plan({caches,defaultBranch:'main',pullStates:new Map(),now,budgetBytes:300,...extra});}
test('only latest key per main cache family retained',()=>assert.deepEqual(p([c(3,2),c(2,3),c(1,4)]).map(d=>d.delete),[false,true,true]));
test('Rust architectures, npm/pip and transport recognized, unrelated data excluded',()=>{assert.ok(family('v0-rust-checks-Windows_NT-x64-b658425a-9d6056e4'));assert.ok(family('setup-python-Linux-x64-24.04-Ubuntu-python-3.12.12-pip-abcdef'));assert.equal(family('model-checkpoint-abcd'),null);assert.notEqual(family('node-cache-Linux-x64-npm-abcd'),family('node-cache-Windows-x64-npm-abcd'));});
test('open or unknown PR preserved, closed PR removed',()=>{const a=c(1,5,{ref:'refs/pull/58/merge'});assert.equal(p([a])[0].delete,false);assert.equal(p([a],{pullStates:new Map([[58,'open']])})[0].delete,false);assert.equal(p([a],{pullStates:new Map([[58,'closed']])})[0].delete,true);});
test('any active build or waiting deployment freezes cache deletion',()=>assert.ok(p([c(2,2),c(1,9)],{active:true}).every(d=>!d.delete)));
test('last access and newly-created cache each have 24h grace',()=>{const a=c(1,5,{last_accessed_at:new Date(now-DAY/2).toISOString()});assert.equal(p([c(2,0.5),a],{budgetBytes:1}).some(d=>d.delete),false);});
test('LRU budget evicts old tag and branch caches, never latest main',()=>{const rows=p([c(3,2),c(2,3,{ref:'refs/heads/refs/tags/v3.6.15'}),c(1,4,{ref:'refs/tags/v3.6.14'})],{budgetBytes:150});assert.deepEqual(rows.map(d=>d.delete),[false,true,true]);});
test('transport fixtures expire while latest ordinary main key remains',()=>assert.equal(p([c(1,2,{key:'actions-transport-Linux-123'})])[0].delete,true));
test('unused dependency cache ages out after seven days',()=>assert.equal(p([c(1,8)])[0].delete,true));
test('invalid/future timestamps and unknown ref never deleted',()=>{for(const extra of [{created_at:'invalid'},{last_accessed_at:'invalid'},{created_at:new Date(now+DAY).toISOString()},{ref:'unknown'}]) assert.equal(p([c(1,20,extra)])[0].delete,false);});
test('unknown cache types survive even above soft budget',()=>assert.equal(p([c(1,20,{key:'production-data'})],{budgetBytes:1})[0].delete,false));
test('destructive API rejects release assets, logs, runs, refs, packages and settings',async()=>{let requests=0;const api=createApi('gaopengbin/geod-global','test',async()=>{requests++;return new Response(null,{status:204});});for(const path of ['releases/assets/42','actions/runs/42','actions/runs/42/logs','git/refs/heads/main','packages/42','actions/cache/storage-limit','actions/caches/../releases/42']) await assert.rejects(api(path,'DELETE'));assert.equal(requests,0);await api('actions/caches/42','DELETE');await api('actions/artifacts/43','DELETE');assert.equal(requests,2);});
test('404 is absence, not successful reclamation, and API errors abort',async()=>{assert.equal(await createApi('gaopengbin/geod-global','test',async()=>new Response(null,{status:404}))('actions/caches/1','DELETE'),null);await assert.rejects(createApi('gaopengbin/geod-global','test',async()=>new Response(null,{status:500}))('actions/caches/1','DELETE'));});
test('pagination completes before cleanup planning and partial errors fail closed',async()=>{let calls=0;const result=await list(async()=>({actions_caches:++calls===1?Array.from({length:100},(_,id)=>c(id+1)):[] }),'actions/caches','actions_caches');assert.equal(calls,2);assert.equal(result.length,100);await assert.rejects(list(async()=>null,'actions/caches','actions_caches'));});
test('active detection excludes only own maintenance run, checks all waiting states',async()=>{const statuses=[];assert.equal(await activeRuns(async path=>{statuses.push(path);return {workflow_runs:path.includes('status=waiting')?[{id:9}]:[{id:1}]};},'1'),true);assert.ok(statuses.some(p=>p.includes('waiting')));});
